class Router:
    def __init__(self):
        self.routes = {
            '/': 'home',
            '/health': 'ok'
        }

    def resolve(self, path):
        if path in self.routes:
            return self.routes[path]
        return None

    def paths_for(self, target):
        return sorted([path for path, t in self.routes.items() if t == target])
